class Solution { bool possible(vector<int>& nums,int k,int limit){int count=0;for(int i=0;i<(int)nums.size();){if(nums[i]<=limit){++count;i+=2;}else ++i;}return count>=k;}public:int minCapability(vector<int>& nums,int k){int left=*min_element(nums.begin(),nums.end()),right=*max_element(nums.begin(),nums.end());while(left<right){int middle=left+(right-left)/2;if(possible(nums,k,middle))right=middle;else left=middle+1;}return left;} };
